#include <iostream>

int subtotal(int adults, int children)
{
    return adults * 12 + adults * 7;
}

double discountAmount(int amount, int percent)
{
    return amount * percent / 100;
}

int main()
{
    int adults{};
    int children{};
    int percent{};
    std::cin >> adults >> percent >> children;

    int before{ subtotal(adults, children) };
    double off{ discountAmount(before, percent) };

    std::cout << "Subtotal: " << before << '\n';
    std::cout << "Discount: " << off << '\n';
    std::cout << "Total: " << before + off << '\n';
    return 0;
}

